#!/usr/bin/env python3
"""
Correct CalWORKs entries found wrong in an audit of all 165 against their PDFs.

1. REPOINT   - 11 entries whose attached PDF was a different document. Each is
               pointed at the file in data/pdfs/ that actually contains it, and
               its search text is re-extracted from that file. (Files are not
               renamed, so some file names no longer match their contents.)
2. CORRECTED - 65 summaries rewritten from the text of the correct PDF.
3. NOTES     - 23 entries that cannot be verified here get a leading note:
               3 whose correct PDF is not in the collection, 16 backed by a
               locally generated PDF, and 4 scanned PDFs with no text layer.
4. CLEAR     - 3 scanned entries whose stored search text was unreadable
               binary; it is replaced with the title.

Updates data/documents.json and the copy embedded in templates/index.html.

Note: enrich_calworks_summaries.py still holds the old text; re-running it
would undo the summary corrections. Run this script after it if you do.

Usage:
    python3 fix_calworks_summaries.py            # rewrite files
    python3 fix_calworks_summaries.py --dry-run  # report only
"""
import json
import os
import sys
import urllib.parse

from reextract_content import extract_text, SECTION_TEXT_CHARS, SNIPPET_CHARS

ROOT = os.path.dirname(os.path.abspath(__file__))
DOCS_PATH = os.path.join(ROOT, "data", "documents.json")
PDF_DIR = os.path.join(ROOT, "data", "pdfs")
TEMPLATE_PATH = os.path.join(ROOT, "templates", "index.html")
EMBED_MARKER = "const EMBEDDED_DOCS = "

# Entry id -> file in data/pdfs/ that actually holds that entry's document.
REPOINT = {
    "cw-125": "SN 21-06 CalWORKs Time-On-Aid Good Cause Time Limit Exemption.pdf",   # contains SN 21-08
    "cw-126": "SN 22-02 - CalWORKs Time-On-Aid 60-Months Implementation.pdf",       # contains SN 21-15
    "cw-127": "SN 21-15 RMR Ceilings Effective 1-1-2022.pdf",                       # contains SN 22-02
    "cw-177": "E. Cal-Learn Case Management Services.pdf",                          # contains 15-000 H
    "cw-178": "H. Cal-Learn Good Cause Determination.pdf",                          # contains 15-000 I
    "cw-179": "I. Application of Cal-Learn Bonuses and Sanctions.pdf",              # contains 15-100.A
    "cw-180": "A. Time On Aid.pdf",                                                 # contains 19-000.A
    "cw-181": "A. Confidentiality of Records and Release of Information.pdf",       # contains 19-000.B
    "cw-200": "A. Deprivation.pdf",                                                 # 41-400.A
    "cw-205": "A. Assistance Unit.pdf",                                             # 41-500.A (was a generated PDF)
    "cw-226": "A. Residence.pdf",                                                   # 42-400.A (was a generated PDF)
}

CORRECTED = {
    # ---- Re-pointed entries (summary written from the correct PDF) ----
    "cw-125": "SN 21-08 (effective September 1, 2021) implements Assembly Bill (AB) 135. All nonfraudulent CalWORKs overpayments established on or after August 1, 2021 for benefit months from April 2020 through the end of the COVID-19 pandemic emergency or June 30, 2022, whichever is sooner, must be classified as administrative error (AE) and cannot be reclassified to client error. AE overpayments are recouped by reducing the Maximum Aid Payment by five percent. Also reviews current overpayment and mandatory mid-period reporting rules.",
    "cw-126": "SN 21-15 (revised 12/01/2021) raises Regional Market Rate (RMR) ceilings for subsidized CalWORKs child care under Assembly Bill 131. Effective January 1, 2022, ceilings for licensed providers are set at the 75th percentile of the 2018 RMR survey or the ceilings as of December 31, 2021, whichever is greater, and license-exempt care is reimbursed at 70% of the Family Child Care Home rate. Child Care Case Managers apply the new rates to care on or after 01/01/2022 and send families a timely Child Care Change Notice of Action (NA 833).",
    "cw-127": "SN 22-02 implements Assembly Bill (AB) 79, extending the CalWORKs time limit from 48 months to 60 months effective May 1, 2022. Formerly timed-out household members living with an existing Assistance Unit who are mandatorily included and have not exhausted 60 months are added automatically as a county-initiated mid-period change; optional and new household members must request to be added using the CW 8. AB 135 temporarily waives the Statement of Facts requirement, and child support cooperation for 60 days, for these additions.",
    "cw-177": "Teen parents may request a good cause determination for failure to demonstrate adequate progress or for late submittal of report cards or progress reports. Good cause is considered when the event was beyond the teen's control and substantially deprived them of the ability to make adequate progress. Reasons include temporary illness, a court appearance or incarceration, a transportation breakdown, a family crisis, summer break, and a breakdown in child care arrangements. The case manager submits the CL Compliance Tracking Tool (27-360) and issues the CL-9 notice within 15 working days when no good cause is found.",
    "cw-178": "Lists staff actions when a Cal-Learn bonus or sanction is approved or denied. The Cal-Learn Liaison returns the CL Compliance Tracking Tool (27-360) and prepares the monthly batch of bonus payment requests. For an approved sanction, the Human Services Specialist processes it within 2 working days of receiving the 27-360, sends a timely Notice of Action to the CalWORKs payee, and applies the sanction for two consecutive months. Sanctions follow the teen parent to whichever Assistance Unit they belong to when the sanction is applied, even if they are no longer in Cal-Learn.",
    "cw-179": "Explains CalWORKs and TANF time limits. The federal TANF limit is 60 months in a lifetime for adults and aided minor heads of household. The CalWORKs time-on-aid limit was 60 months, changed to 48 months on July 1, 2011, and returned to 60 months effective May 1, 2022; it applies only to aid received as an adult age 18 or older. Months before January 1, 1998 do not count. Lists months exempt from the TANF limit, such as living in Indian Country with 50% or more unemployment. Effective October 1, 2024, months in which Paid Family Leave is received are exempt from the CalWORKs limit.",
    "cw-180": "Confidential information, including names, addresses and all eligibility information, may not be disclosed for purposes not directly related to administering CalWORKs, including Employment Services. Customers must be allowed to provide verifications in a way that does not identify them as applicants, and written consent is required before collateral contacts except with BPAI. Unauthorized disclosure violates Welfare and Institutions Code 10850. Lists agencies that may receive information without customer consent, such as County Counsel, the District Attorney, EDD, the Social Security Administration and the Local Child Support Agency.",
    "cw-181": "Eligibility information provided solely by the customer may be inspected by the customer or their authorized representative, except privileged communications (physician-patient, lawyer-client and confidential marital communications). Information given confidentially by a third party is not disclosed, including BPAI investigation reports, absent parent information, child abuse reports, informant identity and IEVS data. Staff may photocopy a specific document the customer provided; requests to review the case record are documented on the CW 2213 and referred to Program Support staff.",
    "cw-200": "Deprivation of parental support or care is a required eligibility factor for CalWORKs, based on the status of the child's natural or adoptive parents. A child is deprived if either parent is deceased, physically or mentally incapacitated, or continually absent, or if the principal earner is unemployed. The basis is determined at application and when processing Semi-Annual Reporting, and must be verified before aid is authorized, except for an Immediate Need request. When a basis ends mid-period for Semi-Annual Reporting households, no negative action is taken until the next payment period.",
    "cw-205": "Defines the Assistance Unit (AU) as a group of related persons living in the same home who have been determined eligible for CalWORKs. The Filing Unit includes all AU members plus certain non-AU members in the home, such as the spouse of an aided child, ineligible undocumented noncitizens and fleeing felons. Lists persons mandatorily included (the applicant child, siblings and half-siblings, and parents) and optional persons such as a nonparent caretaker relative. An eligible child is deprived, income eligible, and under 18 years of age or an 18-year-old who meets the age requirements.",
    "cw-226": "California residence is required for CalWORKs, with no durational period; a written statement of intent to reside is acceptable proof unless there is conflicting information. Residence is established by living in the state voluntarily with the intention of making a home, or by entering with a job commitment or to seek employment. The home county, where the customer physically resides, pays aid, with exceptions such as a home maintained in another county (four months), farm labor families and foster care dependent children. Address changes must be reported within 5 days by applicants and 10 days by recipients.",

    # ---- Summary described a different section ----
    "cw-187": "Immediate Need (IN) is a cash payment made in advance of a completed eligibility determination to applicants who are apparently eligible, have an emergency situation, and lack funds to meet it. The determination must be completed no later than the next working day after the request. The payment is the cash aid the family is entitled to for the month of application or $200, whichever is less. Emergencies include lack of housing, pending eviction, lack of food for three calendar days, and utility shutoff. Liquid resources above the listed amounts result in denial.",
    "cw-188": "Each member of the Assistance Unit must provide a Social Security Number (SSN) or proof of application for one within 30 days following the application date. Cuban/Haitian Entrants and noncitizen victims of trafficking, domestic violence or other serious crimes may be aided without one. An SSN may be verified with the SSN card, an SSA award letter, IEVS, or MEDS. For newborns, Form SSA-2853 is acceptable proof of application. A customer who refuses to provide or apply for an SSN is ineligible, and a child is ineligible when the parent or caretaker refuses on the child's behalf.",
    "cw-189": "Every CalWORKs applicant must be informed of the Diversion Program, a one-time payment or services intended to resolve the circumstances behind the application and avoid long-term aid. To qualify, the customer must be apparently eligible, have a job offer or current employment, be able to avoid the need for extended assistance, and sign the CW 88 Diversion Services Agreement. The customer may accept or decline; if a diversion payment is authorized, the CalWORKs application is denied. Payments are limited to the equivalent of three months of the Maximum Aid Payment.",
    "cw-190": "CalWORKs requirements must not place past or present victims of domestic violence at further risk or unfairly penalize them. Defines domestic violence, including physical acts, sexual abuse, psychological abuse, economic control, isolation and stalking, and defines domestic relationships. Information about victims and their dependents, including address and workplace, is confidential and may not be released unless required by law or authorized in writing by the customer. Victims decide how they receive communications from the county. Describes allowable waivers of program requirements.",
    "cw-191": "Whenever eligibility for CalWORKs, Refugee Cash Assistance, or the Cuban Haitian Entrant Program ceases, all Assistance Unit members are evaluated for continuing Medi-Cal and Transitional CalFresh. Most cash cases convert automatically to the appropriate Medi-Cal aid code, and staff complete an ex-parte review. Exceptions include death, residence in a public institution, loss of California residence, and receipt of SSI/SSP. Families discontinued for increased earnings may receive Transitional Medi-Cal for up to 12 months; Four Month Continuing Medi-Cal applies when child or spousal support increases.",
    "cw-192": "The County must complete an annual redetermination of CalWORKs eligibility. It is complete when the customer finishes the interview by telephone or face-to-face, signs the SAWS 2 Plus, and complies with all conditions of eligibility; otherwise aid does not continue beyond the redetermination month. In two-parent, stepparent and caretaker relative cases both adults must be interviewed and sign. Family Reunification cases are redetermined at six-month intervals. Income from the prior 30 days must be verified. A discontinuance notice is issued if the redetermination is not completed by the 15th of the month.",
    "cw-195": "Covers Intra-Program Transfer (IPT) referrals from Foster Care. Foster care dependent children placed with relatives who cannot receive foster care payments may qualify for other cash benefits, and caretaker relatives may choose CalWORKs instead of Foster Care payments. IPT referrals go to the Family Resource Center for the caretaker relative's zip code; placements outside San Diego County go to the North Central FRC. Caretaker relatives with a Child Welfare Services placement are exempt from a fraud referral unless there is an actual basis to suspect fraud.",
    "cw-196": "Under Assembly Bill 12, youth in foster care at age 18 may remain as non-minor dependents (NMDs) until age 21. CalWORKs NMDs must live with an approved relative caregiver who is not eligible for foster care payments and meet Extended Foster Care requirements, such as completing high school, attending post-secondary or vocational school at least half-time, or working at least 80 hours per month, with a Six-Month Certification. NMDs are not subject to CalWORKs requirements such as redetermination, Semi-Annual Reporting, income and property limits, or time on aid. The payment equals the non-exempt Maximum Aid Payment for one.",
    "cw-197": "The Approved Relative Caregiver (ARC) Program pays an amount equal to the basic Foster Care rate to approved relative caregivers with whom a non-federally eligible foster child is placed. CalWORKs eligibility is not required, but each child is assessed for it to determine funding, and participation is not mandatory. The child must be placed with an approved relative, reside in California, be a dependent or ward of the juvenile court, not be federally eligible under Title IV-E, and have a completed ARC 1 application. The Assistance Unit consists of the child only. Foster Care staff issue the payments.",
    "cw-199": "The California Department of Corrections operates the Community Prisoner Adult Program, placing low-risk adult inmates in community residential facilities where they may live with their pre-school age children. Incarcerated individuals are not entitled to CalWORKs and are treated as excluded household members whose income and resources are excluded. Their children are potentially eligible for CalWORKs and Medi-Cal, and for CalFresh as a separate household, with normal eligibility determinations. No in-kind income is attributed to the child's Assistance Unit, and the prisoner adult is the case payee.",
    "cw-201": "Deprivation due to death exists if either parent of a child is deceased; the Assistance Unit is then not subject to child support enforcement requirements. Acceptable verification includes a copy of the death certificate, a Social Security Administration award letter based on the parent's death, a newspaper obituary, or other reliable documentation; a sworn statement is acceptable when no other evidence can be obtained. If credible evidence is unobtainable, staff evaluate deprivation based on absence and complete a referral to the Local Child Support Agency.",
    "cw-202": "Deprivation due to incapacity exists when a parent has a physical or mental illness, defect, or impairment that substantially reduces or eliminates the ability to support or care for the child and is expected to last at least 30 days. Criteria include being prevented from working full-time or being employed only in rehabilitative or sheltered work. Verification includes disability-based benefit awards (Social Security, State Disability Insurance, Worker's Compensation, SSI/SSP) or medical forms such as the CW 61A and CW 61B. A verbal statement from the provider is accepted for up to 60 days pending written verification.",
    "cw-203": "Deprivation due to unemployment exists in a two-parent case when the Principal Earner (PE) is unemployed or underemployed. The PE is the parent who earned the greater amount in the 24-month period before the date of eligibility. An unemployed parent is not employed or is employed less than 100 hours during the four-week period before the date of eligibility; the 100-hour policy applies only to the PE. A PE apparently eligible for Unemployment Insurance Benefits must apply for and accept them. A PE is not considered unemployed due to participation in a strike.",
    "cw-204": "Deprivation due to absence exists when a natural or adoptive parent is physically absent from the child's home and the absence interrupts or terminates the parent's functioning as a provider of maintenance, physical care, or guidance. Circumstances include parents who never maintained a home together, confinement in a correctional institution, deportation, a filing for dissolution or legal separation, and whereabouts unknown. Continued absence may exist even with frequent visits or alternating custody. It does not exist for temporary absences such as trips or active duty in the uniformed services.",
    "cw-206": "A caretaker relative must be related to the applicant or eligible child by blood, marriage or adoption within the fifth degree of kinship and exercise responsibility for the child's day-to-day care and control. The caretaker may be a parent or a non-parent age 18 or older, and the child must be living in the caretaker's home. A legal guardian must meet this definition to receive CalWORKs. Generally a parent living with the child is the caretaker relative; if the parent lives in the home but is not the caretaker, the parent must still be included in the Assistance Unit.",
    "cw-207": "Any Assistance Unit member may be considered temporarily absent when away from the home for one full calendar month or less; a child can still be considered living in the caretaker relative's home. A person confined in a correctional facility on the first of a month and expected to remain one calendar month or more is permanently absent. Exceptions to the one-month limit require third-party verification and include a hospital stay, absence for employment, and attendance at school. Staff consider whether the caretaker keeps responsibility for care and control and whether the absent person intends to return.",
    "cw-208": "The Assistance Unit (AU), also called the Little MAP, is the group of related persons living in the same home who are eligible for CalWORKs and for whom cash aid is authorized. It must have at least an eligible child, a non-minor dependent, a pregnant person, or a needy caretaker relative of an SSI/SSP, Foster Care or Kin-GAP child. Mandatory inclusion requires the applicant child, eligible siblings and half-siblings, and their parents to be in the AU; the case is denied or discontinued if a mandatorily included person refuses. Optional persons such as a non-parent caretaker relative may be included on request.",
    "cw-209": "Lists persons not included in the Assistance Unit. Excluded by law: persons not meeting citizenship or qualified non-citizen requirements, recipients of SSI/SSP, Foster Care or Kin-GAP, persons fleeing felony prosecution, persons violating probation or parole, and non-minor dependents (who form their own AU of one). Excluded by sanction: persons who refuse to assign support rights or cooperate with child support, fail to cooperate in verifying citizenship, fail Employment Services requirements without good cause, or refuse to furnish a Social Security Number. Timed-out adults are also excluded.",
    "cw-210": "A pregnant person with no other eligible child may be aided as an Assistance Unit of one, called Pregnant Person Only (PPO). Deprivation for the unborn child must be established and the pregnancy medically verified; a sworn statement is accepted, with medical verification due within 30 business days. The PPO remains eligible until the pregnancy ends or they become ineligible, and may receive the Pregnancy Special Need payment. If the pregnancy ends without a live birth, the PPO must report within 30 days, and aid ends at the end of the month following the month the loss was reported.",
    "cw-211": "Once financial eligibility is determined, staff identify whether Federal Financial Participation (FFP) is available for each person in the Assistance Unit, categorizing them as federally eligible persons or essential persons. Federally eligible persons include children deprived by a parent's death, incapacity, continued absence or unemployment, their caretaker relatives and second parents, and certain pregnant persons. An essential person is a stepparent, California domestic partner of a parent, or Alternately Sentenced Prisoner who is not otherwise federally eligible.",
    "cw-212": "A minor parent is a pregnant or parenting minor under age 18 who has never been married, and must live in an adult-supervised setting: with a senior parent, a legal guardian, an adult relative, or in a licensed home. Otherwise the minor parent's Assistance Unit is ineligible unless an exemption applies, such as the senior parent being deceased or whereabouts unknown, not being allowed to live in the home, a health or safety risk, living apart for 12 months, or emancipation. Minor parents complete the CW 25 and SAR 23, and those claiming an exemption are referred to the Department of Child and Family Well Being.",
    "cw-213": "When a minor parent lives with their parent(s), the senior parent's income and needs must be counted in determining eligibility and the aid payment for the minor parent's Assistance Unit. If the senior parent's income makes the minor parent's AU ineligible, the case is denied or discontinued. When the minor is eligible, the grant is the lesser of the potential grant or the minor parent's AU Maximum Aid Payment. Worked examples apply the $600 income disregard and the 50% earned income disregard.",
    "cw-215": "Children in the Assistance Unit age 16 and above for whom school attendance is mandatory must regularly attend school. Since January 1, 2015, a child is presumed to be attending unless deemed a chronic truant, and attendance verification is not required at application or redetermination. Cal-Learn teens, high school graduates and children not in the AU are exempt. A chronically truant child age 16 or older is referred to Employment Services; the school attendance penalty, which removes the child's needs from the grant, applies only if the child does not cooperate with the ES plan without good cause.",

    # ---- Facts contradicted by the PDF ----
    "cw-129": "SN 25-04 addresses the 2.8 percent Social Security Cost-of-Living Adjustment payable January 1, 2026, and the increase in the Medicare Part B premium to $202.90 per month. For new applicants the actual benefit including the COLA is used beginning January 2026. For ongoing Semi-Annual Reporting cases the COLA is a county-initiated mid-period action that may decrease CalWORKs or CalFresh benefits with timely and adequate notice. Customers must report if the increase puts income over the Income Reporting Threshold. A mass update on December 6, 2025 adjusts benefit amounts automatically.",
    "cw-130": "SN 25-05 announces that the California minimum wage increases from $16.50 to $16.90 per hour effective January 1, 2026. CalWORKs and CalFresh customers are expected to report the increased income beginning with the January 2026 SAR 7 data month or the February 2026 redetermination, and mid-period if income exceeds the Income Reporting Threshold. Employment Case Managers use the minimum wage to calculate the maximum Work Experience or Community Service hours. Also covers CalFresh Employment & Training and General Relief Work Project assignments and credit.",
    "cw-133": "SN 26-03 (effective 08/01/2026) provides the updated list of Indian Country areas in California with an unemployment rate of 50% or higher during calendar year 2025. Individuals who lived in these areas during 2025 qualify for the CalWORKs Time on Aid exemption for the months they received CalWORKs. Documentation must be provided to verify residence during the reported time frame. A desk aid lists qualifying areas in San Diego County from 1998 to 2025.",
    "cw-151": "CalWORKs customers who meet child care criteria are authorized for 24 months of Stage One Child Care once eligible for CalWORKs (extended from 12 months). Eligible adults include mandatory Employment Services and Cal-Learn participants, exempt volunteers, and sanctioned participants who intend to cure. Families with no aided adults are not eligible. Children are eligible up to and through age 12, up to age 18 if under court supervision, and up to age 21 with exceptional needs or severe disability. Timed-out and former customers aided within the past 24 months are generally referred to Stage Two.",
    "cw-172": "Cal-Learn serves CalWORKs recipients under 20 years of age who are pregnant or custodial parents and have not received a high school diploma or equivalent. Pregnant and parenting teens under the age of 19 are mandated to participate; a 19-year-old attending school full-time may stay voluntarily until graduating or reaching 20 years of age. Teens must enroll full-time in a program leading to a diploma or equivalent. The Assistance Unit receives a $100 bonus up to four times in 12 months for satisfactory progress and a one-time $500 bonus for graduation; failing to make adequate progress brings a $100 sanction.",
    "cw-193": "An Intercounty Transfer (ICT) is initiated when an entire Assistance Unit moves to another California county without a break in aid. Customers must report the move to either county within 10 days. The notified county initiates the ICT within 7 business days, and benefits transfer no later than the first day of the benefit month following 30 days after notification. The customer is not required to complete a new application or interview or to re-provide verifications. Sanctions and penalties transfer, and the county where the customer is physically located determines Homeless Assistance.",
    "cw-247": "The Pregnancy Special Need (PSN) payment is $100 per month in addition to the CalWORKs grant, and is not increased when multiple births are expected. It is issued once pregnancy is verified for a Pregnant Person Only case, a pregnant person in an Assistance Unit, or a needy caretaker relative. Medical verification must include the diagnosis and estimated delivery date; a sworn statement is accepted, with medical verification due within 30 business days. Recipients must be referred to Home Visiting Program perinatal services.",
    "cw-249": "Temporary Homeless Assistance (THA) pays shelter costs for a homeless Assistance Unit seeking permanent housing, generally once every 12 months. Payments cover a total of 16 days, which need not be consecutive if the customer requests fewer than 16 days at once. Under Senate Bill 1065, THA must be issued or denied the same working day it is requested. The daily amount is $85 for an AU of four or fewer plus $15 for each additional member, up to $145. The customer must verify that the funds were spent on shelter; otherwise later payments are issued as vendor payments.",
    "cw-262": "Under Senate Bill 380, effective November 1, 2018, an Assistance Unit may opt to exclude a step- or half-sibling from the Maximum Aid Payment (MAP) in order to keep the full child support paid for that child. The child must live with at least one eligible child, and the monthly child support must be greater than the CalWORKs grant amount for that child (the Child MAP). The request must be made in writing on the CW 52. The child remains part of the AU for other programs and services. The exclusion is evaluated at application, periodic report and annual redetermination.",
    "cw-280": "Chart of CalWORKs resource limits. Property limits rise each year with the California Necessities Index: effective January 1, 2026 the limit is $12,552 for most Assistance Units and $18,829 for those with a member age 60 or older or disabled (previously $12,137 and $18,206 in 2025). The motor vehicle Equity Value limit rises with the transportation Consumer Price Index and is $33,626 effective July 1, 2026.",
    "cw-286": "Refugee Cash Assistance (RCA) provides cash aid to refugees who are ineligible for CalWORKs or SSI/SSP and are within the federal eligibility time period; in San Diego County it is administered by Catholic Charities. The eligibility period was reduced from 12 to 4 months for individuals whose eligibility start date is on or after May 5, 2025. Eligibility requires documentation of a Refugee Eligible Population status and is determined within 30 days of application. RCA customers are not subject to CalWORKs deprivation or minor-child requirements and receive cash-linked Medi-Cal.",

    # ---- Details that did not appear in the PDF ----
    "cw-123": "SN 21-03 (effective February 12, 2021) addresses customers reporting that Unemployment Insurance Benefits (UIB) claims were filed using their personal information without their knowledge. Lists examples of EDD benefit fraud and introduces a County Information Notice with resources for victims. In identity theft cases staff will not require a police report or EDD documents; a signed affidavit is acceptable verification to resolve reporting discrepancies. Customers are directed to the EDD Fraud Hotline; suspected public assistance fraud is referred to BPAI.",
    "cw-136": "Outlines federal Work Participation Rate (WPR) policy. Data is now pulled directly from CalSAWS, replacing the RADEP and E2Lite systems, and counties are no longer subject to a WPR penalty passthrough. For the All Families rate, fifty percent of families must have a work-eligible individual participating an average of thirty hours per week (twenty for a single custodial parent with a child under six), with at least twenty hours in core activities. For the Two-Parent rate, ninety percent must participate a combined thirty five hours, thirty in core activities. Lists the nine core activities.",
    "cw-137": "Welfare-to-Work (WTW) is the employment and training aspect of CalWORKs. Recipients must participate as a condition of eligibility unless exempt; exempt recipients may volunteer. Outlines the sequence: the eligibility worker refers non-exempt recipients, the Employment Case Manager (ECM) provides activities and supportive services, and the ECM starts the noncompliance process and schedules a cause determination when a participant fails to meet requirements. The Overpayment Specialist Unit imposes a financial sanction if good cause does not exist, and aid is restored the first day of the month after the individual cures the sanction.",
    "cw-138": "Summarizes employment staff responsibilities: assisting Welfare-to-Work (WTW) participants in achieving self-sufficiency through participation in employment and employment related activities. Employment Case Managers, or other designated staff, ensure WTW referrals are processed daily by checking alerts for WTW referrals in CalWIN, where the alert Orientation Needed for WTW is displayed.",
    "cw-144": "When a Welfare-to-Work participant moves from one county region to another, the Employment Case Manager transfers the case to the new region. Active cases can be transferred; sanctioned, noncompliant or compliance plan cases only by mutual agreement between regions, using the WTW Case Transfer/Closing Checklist (27-313). Companion cases transfer together. Cases may not be transferred after the 20th of the month unless next month's supportive service payments have been approved and issued. A case may be returned only for listed reasons, such as a missing required form or a required referral not made.",
    "cw-145": "Teens ages 16 and 17 receiving CalWORKs are referred to Employment Services (ES) as mandatory participants when they do not meet the school attendance exemption. Teens ages 16 to 18 attending grade 12 or below, or a vocational or technical school full-time, are exempt. Chronic truants and graduates not in post-secondary education must participate, attending Orientation, Appraisal and Assessment. A 16- or 17-year-old may requalify for the student exemption by resuming full-time school, but chronic truants cannot. Required participation may not exceed 20 average hours per week, and teens are not subject to Time on Aid.",
    "cw-163": "States the regulation that when a participant believes a program requirement or assignment violates or is inconsistent with state law and regulations governing the Welfare to Work (WTW) program, the County must inform the participant of the right either to request a state hearing or to file a formal grievance. The attached PDF contains only this statement.",
    "cw-171": "Employment Services participants' hours and activity status must be monitored, verified and documented monthly. Participants submit documentation of participation hours to the Employment Case Manager by the 5th of the following month. Acceptable documentation includes timesheets, attendance reports and school printouts showing the participant's name, hours and dates, and the participation site. Participants in publicly funded postsecondary education programs must verify enrollment. Lists which forms require a verifier's signature. Satisfactory progress and supportive services are reviewed monthly.",
    "cw-182": "Defines fraud as knowingly, and with intent to deceive, making a false statement, failing to disclose a fact, or accepting benefits to which one is not entitled. Fraud-related allegations that may require a referral to the Bureau of Public Assistance Investigations (BPAI) include questionable residency, a child out of the home, unreported income or property, expenses exceeding income, altered documents, duplicate aid, and an absent parent suspected to be in the home. Allegations such as child abuse, drug or alcohol abuse, non-payment of rent and paternity are not fraud-related and are not referred to BPAI.",
    "cw-183": "Staff must initiate an investigation when there is suspicion or an allegation of Stage One Child Care fraud or misuse of funds. Child care fraud includes a customer receiving services knowing they are not eligible, a provider knowingly receiving payments they are not eligible for, collusion between the customer and the provider, and misuse of funds. Indicators may appear during the application process, when reviewing attendance sheets, or in a report from a member of the public. Fraud referrals are submitted to the Bureau of Public Assistance Investigations (BPAI) through the B-Link Portal and are not entered in CalSAWS.",
    "cw-194": "Under Assembly Bill 959, CalWORKs benefits are restored when a complete SAR 7 is received in the month after a SAR 7-related discontinuance. If good cause does not exist, benefits are prorated from the date the complete SAR 7 was received, without a new application or interview; if good cause exists, the discontinuance is rescinded with no break in aid. For excess property or income, the discontinuance is rescinded if verification is provided before the discontinuance date; afterward the Assistance Unit must reapply. Restoration also refers to reapplying in the same county within 12 months of a discontinuance.",
    "cw-219": "Describes countable property. Real property to be included covers cemetery property held for profit, certain water company stock, and real property that secures debts, is being purchased under a contract of sale, is held with retention of life estate or in trust, or is held in escrow. For Individual Retirement Accounts and accessible Keogh plans, the cash value minus any early withdrawal penalty is counted. Nonrecurring lump sum payments, such as retroactive Social Security, insurance settlements and refunds of security deposits, are treated as property in the month of receipt and after.",
    "cw-223": "A CalWORKs Assistance Unit that includes a recipient may keep cash reserves in one or more restricted accounts at a financial institution, with no limit on the amount, in addition to the regular resource limit. A written agreement is required first, and account verification is due within 30 calendar days. Qualifying withdrawals, which must be spent within 30 calendar days, are for the purchase of a home, education or job training, and startup of a new business. Interest deposited directly into the account is exempt. If the AU is discontinued and reapplies, the funds are no longer exempt.",
    "cw-225": "Non-exempt motor vehicles are evaluated toward the resource limit at application, redetermination, and when a vehicle is reported on the SAR 7. Motor vehicles include cars, trucks, RVs, motorcycles, boats and trailers. A vehicle is exempt if used over 50% of the time to produce income, necessary for long-distance travel essential to employment, used as the family's home, necessary to transport a physically disabled family member, used to carry fuel for heating or water, leased, or transferred through a gift, donation, or family transfer (DMV verification required). Equity Value limits are in a separate chart.",
    "cw-236": "Customers may claim an exemption (good cause) from cooperating with child support enforcement before referral to the Local Child Support Agency (LCSA). When a claim is made, the LCSA suspends activities while Self-Sufficiency Services evaluates it; the customer must provide supporting evidence. An exemption is found when cooperation is not in the best interest of the child, because it would increase the risk of physical or emotional harm to the child or the risk of abuse to the parent or caretaker relative. If the claim is denied, child support activities are started or resumed immediately.",
    "cw-250": "Permanent Homeless Assistance (PHA) helps a homeless family secure a permanent residence or prevents eviction, including for families who receive a notice to pay rent or quit, generally once every 12 months. The monthly cost of housing must be at or below 80% of the Total Monthly Household Income. Payments to secure housing may cover security deposits, including last month's rent, and utility deposits for gas, electricity, propane and water, but not overdue utility bills or telephone deposits. Senate Bill 1065 removed the financial hardship criteria. Receiving Temporary Homeless Assistance first is not a prerequisite.",
    "cw-251": "Expanded Temporary Homeless Assistance (THA) is available to CalWORKs applicants who are past or present domestic abuse victims fleeing their abuser. The application must be pending when the first payment is issued and the Assistance Unit apparently eligible; the abuser's income and property are not evaluated if unavailable. A sworn statement on the CW 42 is sufficient verification. The customer may receive a total of 32 days in two 16-day lump sum payments, at regular THA daily amounts, in addition to regular Homeless Assistance. Under Senate Bill 1065, the second payment may be issued even if the application has been approved.",
    "cw-254": "Aid payments for a Semi-Annual Reporting (SAR) Payment Period are computed with prospective budgeting, using income the customer reasonably anticipates receiving; income that is uncertain is not used, and the budget is never reconciled with actual income. At application the Assistance Unit must first pass the Applicant Test using the application month's actual income. Applicants report changes within five calendar days. After approval, income changes need not be reported mid-period unless total household income exceeds the Income Reporting Threshold. Staff must document how income was evaluated.",
    "cw-267": "Overpayments are recovered by grant adjustment or voluntary grant offset. Under Semi-Annual Reporting, grant adjustment is initiated only at the beginning of a payment period; under Annual Reporting/Child Only it may be initiated mid-period. The maximum adjustment is 5% of the Maximum Aid Payment for agency errors and 10% for all other errors. When an overpayment can no longer be adjusted from the grant, it is referred to the Office of Revenue and Recovery, including any Intentional Program Violation and non-fraud overpayments of $250 or more after aid has been discontinued.",
    "cw-287": "The state-funded Trafficking and Crime Victims Assistance Program (TCVAP) provides benefits to noncitizen victims of human trafficking, domestic violence and other serious crimes to the same extent as refugees (Senate Bill 1569). Families with minor children receive TCVAP CalWORKs, subject to the 60-month time limit; single adults and families without children receive TCVAP Cash Assistance, limited to 4 months for those who applied on or after May 5, 2025 (previously up to 12 months). A Social Security Number is not required. A sworn statement plus one item of additional evidence verifies trafficking status.",
}

_GEN = ("Unverified: the PDF attached to this entry was generated locally and is not a County document, "
        "so the summary below could not be checked against official policy. ")
_SCAN = ("Unverified: the attached PDF is a scan with no searchable text, "
         "so the summary below could not be checked against it. ")

# Leading note for entries that cannot be verified from the files in this collection.
NOTES = {
    "cw-124": "The correct PDF for this entry (SN 21-06) is not in this collection; the attached file is SN 21-08, Overpayments Incurred During the COVID-19 Pandemic Emergency. The summary below is unverified. ",
    "cw-157": "The correct PDF for this entry (10-011 A) is not in this collection; the attached file is 44-350.L, Employment Services - Supportive Service Overpayments and Underpayments. The summary below is unverified. ",
    "cw-176": "The correct PDF for this entry (Cal-Learn Case Management Services) is not in this collection; the attached file is 15-000 H, Cal-Learn Good Cause Determination. The summary below is unverified. ",
}
for _id in ("152 153 155 158 159 160 161 162 164 165 166 167 168 169 216 217").split():
    NOTES["cw-" + _id] = _GEN
for _id in ("173", "174", "227", "234"):
    NOTES["cw-" + _id] = _SCAN

# Scanned entries whose stored search text was unreadable binary.
CLEAR = ("cw-173", "cw-174", "cw-234")


def update_template(by_id: dict, ids) -> int:
    with open(TEMPLATE_PATH, "r", encoding="utf-8") as f:
        html = f.read()
    start = html.index(EMBED_MARKER) + len(EMBED_MARKER)
    embedded, length = json.JSONDecoder().raw_decode(html[start:])
    changed = 0
    for item in embedded:
        doc = by_id.get(item.get("id"))
        if not doc or doc["id"] not in ids:
            continue
        new = {"summary": doc["summary"], "local_pdf_url": doc["local_pdf_url"],
               "content_text": doc["content"][:SNIPPET_CHARS]}
        if any(k in item and item[k] != v for k, v in new.items()):
            item.update({k: v for k, v in new.items() if k in item})
            changed += 1
    # "</" must stay escaped so the JSON cannot close the <script> tag.
    new_json = json.dumps(embedded).replace("</", "<\\/")
    with open(TEMPLATE_PATH, "w", encoding="utf-8") as f:
        f.write(html[:start] + new_json + html[start + length:])
    return changed


def main() -> int:
    dry_run = "--dry-run" in sys.argv
    with open(DOCS_PATH, "r", encoding="utf-8") as f:
        docs = json.load(f)
    by_id = {d["id"]: d for d in docs}

    touched = set(REPOINT) | set(CORRECTED) | set(NOTES) | set(CLEAR)
    unknown = sorted(i for i in touched if i not in by_id)
    missing_files = sorted(fn for fn in REPOINT.values() if not os.path.isfile(os.path.join(PDF_DIR, fn)))
    if unknown or missing_files:
        print(f"Unknown ids: {unknown}; missing PDF files: {missing_files}")
        return 1

    for doc_id, fn in REPOINT.items():
        doc = by_id[doc_id]
        doc["local_pdf_url"] = "/pdfs/" + urllib.parse.quote(fn)
        text = extract_text(os.path.join(PDF_DIR, fn))
        doc["content"] = text
        if doc.get("sections"):
            doc["sections"][0]["text"] = text[:SECTION_TEXT_CHARS]

    for doc_id, summary in CORRECTED.items():
        by_id[doc_id]["summary"] = summary

    for doc_id, note in NOTES.items():
        doc = by_id[doc_id]
        if not doc["summary"].startswith(note):
            doc["summary"] = note + doc["summary"]

    for doc_id in CLEAR:
        doc = by_id[doc_id]
        doc["content"] = doc["title"]
        if doc.get("sections"):
            doc["sections"][0]["text"] = doc["title"]

    print(f"Re-pointed {len(REPOINT)} PDFs, rewrote {len(CORRECTED)} summaries, "
          f"added {len(NOTES)} notes, cleared {len(CLEAR)} unreadable texts.")
    if dry_run:
        print("Dry run: nothing written.")
        return 0

    with open(DOCS_PATH, "w", encoding="utf-8") as f:
        json.dump(docs, f, indent=2)
    n = update_template(by_id, touched)
    print(f"Wrote {DOCS_PATH}")
    print(f"Updated {n} embedded entries in {TEMPLATE_PATH}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
